class LogSettings {
  static #level = 1;                      // one slot per class

  get level()  { return LogSettings.#level; }
  set level(v) { LogSettings.#level = v; }
}

const a = new LogSettings();
const b = new LogSettings();
a.level = 3;
console.log(b.level);                     // 3 - same slot

variants.code_sketch:
class LogSettings {
  static #level = 1;                      // one slot per class

  get level()  { return LogSettings.#level; }
  set level(v) { LogSettings.#level = v; }
}

const a = new LogSettings();
const b = new LogSettings();
a.level = 3;
console.log(b.level);                     // 3 - same slot

const cell = { level: 1 };                     // created once per module

export const createLogSettings = () => ({    // instances share cell
  get level()  { return cell.level; },
  set level(v) { cell.level = v; },
});

const a = createLogSettings();
const b = createLogSettings();
a.level = 3;
console.log(b.level);                        // 3
